Now implement UART and SD monitor modules.

We need to decide on UART instance. We'll use USART1 TX on PA9, 115200 8N1, no RX. Implement in `App/Src/log_uart.c`.

Design:
- `log_uart.h`:
```c
#ifndef LOG_UART_H
#define LOG_UART_H
#include "main.h"
void LOG_Init(void);
void LOG_Write(const char *text);
void LOG_Printf(const char *fmt, ...);
#endif
```
- `log_uart.c`:
```c
#include "log_uart.h"
#include <stdarg.h>
#include <stdio.h>
#include <string.h>

UART_HandleTypeDef huart1;

void LOG_Init(void)
{
  huart1.Instance = USART1;
  huart1.Init.BaudRate = 115200;
  huart1.Init.WordLength = UART_WORDLENGTH_8B;
  huart1.Init.StopBits = UART_STOPBITS_1;
  huart1.Init.Parity = UART_PARITY_NONE;
  huart1.Init.Mode = UART_MODE_TX;
  huart1.Init.HwFlowCtl = UART_HWCONTROL_NONE;
  huart1.Init.OverSampling = UART_OVERSAMPLING_16;
  if (HAL_UART_Init(&huart1) != HAL_OK) { Error_Handler(); }
}
void HAL_UART_MspInit(UART_HandleTypeDef* huart)
{
  GPIO_InitTypeDef GPIO_InitStruct = {0};
  if (huart->Instance == USART1) {
    __HAL_RCC_USART1_CLK_ENABLE();
    __HAL_RCC_GPIOA_CLK_ENABLE();
    GPIO_InitStruct.Pin = GPIO_PIN_9;
    GPIO_InitStruct.Mode = GPIO_MODE_AF_PP;
    GPIO_InitStruct.Pull = GPIO_NOPULL;
    GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_VERY_HIGH;
    GPIO_InitStruct.Alternate = GPIO_AF7_USART1;
    HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);
  }
}
void HAL_UART_MspDeInit(UART_HandleTypeDef* huart) { ... }
void LOG_Write(const char *text) { HAL_UART_Transmit(&huart1, (uint8_t*)text, strlen(text), HAL_MAX_DELAY); }
void LOG_Printf(const char *fmt, ...) { char buf[128]; va_list ap; va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap); LOG_Write(buf); }
```
Note: `HAL_UART_MspInit` is defined in the app, but `stm32f4xx_hal_msp.c` already has `HAL_MspInit` etc. It's fine to define `HAL_UART_MspInit` in another file; the HAL weak function will be overridden. Ensure no duplicate. Good.

Potential issue: `HAL_UART_Transmit` with `HAL_MAX_DELAY` blocks until sent. At 115200, 128 bytes ~11 ms, okay. Could use `HAL_UART_Transmit` with timeout 100.

Now SD monitor:
- `sd_monitor.h`:
```c
void SD_Monitor_Init(void);
void SD_Monitor_Process(void);
```
- `sd_monitor.c`:
```c
