input.content:
#include "lcd_status.h"

#include "fonts.h"

#define LCD_COLOR_BLACK   0x0000U
#define LCD_COLOR_WHITE   0xFFFFU
#define LCD_COLOR_GREEN   0x0400U
#define LCD_COLOR_RED     0x8000U

static uint16_t lcd_status_buffer[LCD_STATUS_WIDTH * LCD_STATUS_HEIGHT]
    __attribute__((aligned(4)));

static const char *const TEXT_PRESENT = "Presence carte : OUI";
static const char *const TEXT_ABSENT  = "Presence carte : NON";

static void LCD_Fill(uint16_t color)
{
    for (uint32_t i = 0U; i < (LCD_STATUS_WIDTH * LCD_STATUS_HEIGHT); ++i)
    {
        lcd_status_buffer[i] = color;
    }
}

static void LCD_DrawChar(uint16_t x, uint16_t y, char c, uint16_t fg, uint16_t bg)
{
    const sFONT *font = &Font16;
    const uint16_t width = font->Width;
    const uint16_t height = font->Height;
    const uint8_t bytes_per_row = (uint8_t)((width + 7U) / 8U);
    const uint16_t pad = (uint16_t)(8U * bytes_per_row - width);
    const uint8_t *glyph;

    if (c < 0x20 || c > 0x7E)
    {
        c = '?';
    }

    glyph = &font->table[(uint32_t)(c - 0x20) * height * bytes_per_row];

    for (uint16_t row = 0U; row < height; ++row)
    {
        uint32_t line = 0U;
        for (uint8_t b = 0U; b < bytes_per_row; ++b)
        {
            line = (line << 8) | glyph[(row * bytes_per_row) + b];
        }

        for (uint16_t col = 0U; col < width; ++col)
        {
            uint16_t px = (uint16_t)(x + col);
            uint16_t py = (uint16_t)(y + row);
            if (px >= LCD_STATUS_WIDTH || py >= LCD_STATUS_HEIGHT)
            {
                continue;
            }

            if ((line & (1UL << (width - col + pad - 1U))) != 0U)
            {
                lcd_status_buffer[(uint32_t)py * LCD_STATUS_WIDTH + px] = fg;
            }
            else
            {
                lcd_status_buffer[(uint32_t)py * LCD_STATUS_WIDTH + px] = bg;
            }
        }
    }
}

static void LCD_DrawText(const char *text, uint16_t x, uint16_t y, uint16_t fg, uint16_t bg)
{
    while (*text != '\0')
    {
        LCD_DrawChar(x, y, *text, fg, bg);
        x = (uint16_t)(x + Font16.Width);
        ++text;
    }
}

void LCD_Status_ConfigureLayer(LTDC_HandleTypeDef *hltdc)
{
    LTDC_LayerCfgTypeDef layer = {0};

    layer.WindowX0 = 0U;
    layer.WindowX1 = LCD_STATUS_WIDTH;
    layer.WindowY0 = 0U;
    layer.WindowY1 = LCD_STATUS_HEIGHT;
    layer.PixelFormat = LTDC_PIXEL_FORMAT_RGB565;
    layer.Alpha = 0xFFU;
    layer.Alpha0 = 0U;
    layer.BlendingFactor1 = LTDC_BLENDING_FACTOR1_CA;
    layer.BlendingFactor2 = LTDC_BLENDING_FACTOR2_CA;
    layer.FBStartAdress = (uint32_t)lcd_status_buffer;
    layer.ImageWidth = LCD_STATUS_WIDTH;
    layer.ImageHeight = LCD_STATUS_HEIGHT;
    layer.Backcolor.Red = 0U;
    layer.Backcolor.Green = 0U;
    layer.Backcolor.Blue = 0U;

    if (HAL_LTDC_ConfigLayer(hltdc, &layer, 0U) != HAL_OK)
    {
        Error_Handler();
    }
}

void LCD_Status_SetCardPresent(int present)
{
    uint16_t bg = present ? LCD_COLOR_GREEN : LCD_COLOR_RED;
    const char *text = present ? TEXT_PRESENT : TEXT_ABSENT;
    const uint16_t text_width = (uint16_t)(20U * Font16.Width);
    const uint16_t x = (LCD_STATUS_WIDTH > text_width) ? (uint16_t)((LCD_STATUS_WIDTH - text_width) / 2U) : 0U;
    const uint16_t y = (LCD_STATUS_HEIGHT > Font16.Height) ? (uint16_t)((LCD_STATUS_HEIGHT - Font16.Height) / 2U) : 0U;

    LCD_Fill(bg);
    LCD_DrawText(text, x, y, LCD_COLOR_WHITE, bg);
}

void LCD_Status_Init(void)
{
    LCD_Status_SetCardPresent(0);
}

uint16_t *LCD_Status_GetBuffer(void)
{
    return lcd_status_buffer;
}

