#include "lcd_status.h"

#include "app_info.h"
#include "stm32f429i_discovery_lcd.h"

static const char TEXT_VERSION[] = APP_NAME " v" APP_VERSION;
static const char TEXT_PRESENT[] = "Presence carte : OUI";
static const char TEXT_ABSENT[]  = "Presence carte : NON";

void LCD_Status_Init(void)
{
    (void)BSP_LCD_Init();

    BSP_LCD_LayerDefaultInit(0U, LCD_FRAME_BUFFER);
    BSP_LCD_SelectLayer(0U);
    BSP_LCD_SetLayerVisible(0U, ENABLE);

    BSP_LCD_SetFont(&Font12);
    BSP_LCD_SetTextColor(LCD_COLOR_BLACK);
    BSP_LCD_SetBackColor(LCD_COLOR_WHITE);
    BSP_LCD_Clear(LCD_COLOR_WHITE);

    LCD_Status_SetCardPresent(0);
}

void LCD_Status_SetCardPresent(int present)
{
    BSP_LCD_SetFont(&Font12);
    BSP_LCD_SetBackColor(LCD_COLOR_WHITE);
    BSP_LCD_Clear(LCD_COLOR_WHITE);

    BSP_LCD_SetTextColor(LCD_COLOR_BLUE);
    BSP_LCD_DisplayStringAt(0U, 10U, (uint8_t *)TEXT_VERSION, CENTER_MODE);

    BSP_LCD_SetTextColor(present ? LCD_COLOR_GREEN : LCD_COLOR_RED);
    BSP_LCD_DisplayStringAt(0U, 30U, (uint8_t *)(present ? TEXT_PRESENT : TEXT_ABSENT), CENTER_MODE);
}

