    LTDC_HandleTypeDef hltdc = {0};
    LTDC_LayerCfgTypeDef layer = {0};
    hltdc.Instance = LTDC;
    layer.WindowX0=0; layer.WindowX1=240; layer.WindowY0=0; layer.WindowY1=320;
