#include "lcd_status.h"

#include <string.h>

#include "app_info.h"
#include "log_uart.h"
#include "stm32f429i_discovery_lcd.h"

#define LCD_WIDTH  240U
#define LCD_HEIGHT 320U

#define LCD_COLOR_WHITE  0xFFFFU
#define LCD_COLOR_BLACK  0x0000U
#define LCD_COLOR_BLUE   0x001FU
#define LCD_COLOR_GREEN  0x07E0U
#define LCD_COLOR_RED    0xF800U

static const char TEXT_VERSION[] = "F429 SD v" APP_VERSION;
static const char TEXT_PRESENT[] = "Presence carte : OUI";
static const char TEXT_ABSENT[]  = "Presence carte : NON";

static uint16_t *const LCD_FB = (uint16_t *)LCD_FRAME_BUFFER;

static void LCD_SDRAM_Test(void)
{
    uint32_t pattern[4] = {0x12345678U, 0xA5A5A5A5U, 0xDEADBEEFU, 0x55AA55AAU};
    uint32_t readback[4] = {0U, 0U, 0U, 0U};
    uint32_t address = 0xD0100000U;
    uint8_t write_result = BSP_SDRAM_WriteData(address, pattern, 4U);
    uint8_t read_result = BSP_SDRAM_ReadData(address, readback, 4U);
    int ok = (write_result == 0U) && (read_result == 0U) &&
             (memcmp(pattern, readback, sizeof(pattern)) == 0);

    LOG_Printf("SDRAM:%s\r\n", ok ? "OK" : "FAIL");
}

static void LCD_ConfigureRGB565Layer(void)
{
    LTDC_HandleTypeDef hltdc = {0};
    LTDC_LayerCfgTypeDef layer = {0};

    hltdc.Instance = LTDC;

    layer.WindowX0 = 0U;
    layer.WindowX1 = LCD_WIDTH;
    layer.WindowY0 = 0U;
    layer.WindowY1 = LCD_HEIGHT;
    layer.PixelFormat = LTDC_PIXEL_FORMAT_RGB565;
    layer.Alpha = 0xFFU;
    layer.Alpha0 = 0U;
    layer.BlendingFactor1 = LTDC_BLENDING_FACTOR1_CA;
    layer.BlendingFactor2 = LTDC_BLENDING_FACTOR2_CA;
    layer.FBStartAdress = (uint32_t)LCD_FB;
    layer.ImageWidth = LCD_WIDTH;
    layer.ImageHeight = LCD_HEIGHT;
    layer.Backcolor.Red = 0U;
    layer.Backcolor.Green = 0U;
    layer.Backcolor.Blue = 0U;

    if (HAL_LTDC_ConfigLayer(&hltdc, &layer, 0U) != HAL_OK)
    {
        Error_Handler();
    }
}

static void LCD_Fill(uint16_t color)
{
    for (uint32_t index = 0U; index < (LCD_WIDTH * LCD_HEIGHT); ++index)
    {
        LCD_FB[index] = color;
    }
}

static void LCD_DrawChar(uint16_t x, uint16_t y, char c, uint16_t fg, uint16_t bg)
{
    const sFONT *font = &Font16;
    const uint16_t width = font->Width;
    const uint16_t height = font->Height;
    const uint8_t bytes_per_row = (uint8_t)((width + 7U) / 8U);
    const uint16_t pad = (uint16_t)(8U * bytes_per_row - width);
    const uint8_t *glyph;

    if (c < 0x20 || c > 0x7E)
    {
        c = '?';
    }

    glyph = &font->table[(uint32_t)(c - 0x20) * height * bytes_per_row];

    for (uint16_t row = 0U; row < height; ++row)
    {
        uint32_t line = 0U;
        for (uint8_t b = 0U; b < bytes_per_row; ++b)
        {
            line = (line << 8) | glyph[(row * bytes_per_row) + b];
        }

        for (uint16_t col = 0U; col < width; ++col)
        {
            uint16_t px = (uint16_t)(x + col);
            uint16_t py = (uint16_t)(y + row);
            if (px >= LCD_WIDTH || py >= LCD_HEIGHT)
            {
                continue;
            }

            if ((line & (1UL << (width - col + pad - 1U))) != 0U)
            {
                LCD_FB[(uint32_t)py * LCD_WIDTH + px] = fg;
            }
            else
            {
                LCD_FB[(uint32_t)py * LCD_WIDTH + px] = bg;
            }
        }
    }
}

static void LCD_DrawTextCentered(const char *text, uint16_t y, uint16_t fg, uint16_t bg)
{
    const uint16_t width = (uint16_t)(strlen(text) * Font16.Width);
    uint16_t x = (LCD_WIDTH > width) ? (uint16_t)((LCD_WIDTH - width) / 2U) : 0U;

    while (*text != '\0')
    {
        LCD_DrawChar(x, y, *text, fg, bg);
        x = (uint16_t)(x + Font16.Width);
        ++text;
    }
}

void LCD_Status_Init(void)
{
    (void)BSP_LCD_Init();
    LCD_SDRAM_Test();
    LCD_ConfigureRGB565Layer();

    LCD_Status_SetCardPresent(0);
}

void LCD_Status_SetCardPresent(int present)
{
    uint16_t bg = LCD_COLOR_WHITE;
    uint16_t status_color = present ? LCD_COLOR_GREEN : LCD_COLOR_RED;

    LCD_Fill(bg);
    LCD_DrawTextCentered(TEXT_VERSION, 20U, LCD_COLOR_BLUE, bg);
    LCD_DrawTextCentered(present ? TEXT_PRESENT : TEXT_ABSENT, 60U, status_color, bg);
}

