#include "lvgl.h"
#include "stm32f429i_discovery_lcd.h"

#define LVGL_DRAW_BUF_LINES 40U
#define LVGL_FRAME_BUFFER   ((uint16_t *)LCD_FRAME_BUFFER)

static lv_color_t lvgl_draw_buf[LCD_WIDTH * LVGL_DRAW_BUF_LINES];
static lv_disp_draw_buf_t lvgl_disp_buf;
static lv_disp_drv_t lvgl_disp_drv;

static void LVGL_Flush(lv_disp_drv_t *drv, const lv_area_t *area, lv_color_t *color_p)
{
    uint16_t *frame_buffer = LVGL_FRAME_BUFFER;

    for (lv_coord_t y = area->y1; y <= area->y2; ++y)
    {
        for (lv_coord_t x = area->x1; x <= area->x2; ++x)
        {
            frame_buffer[(uint32_t)y * LCD_WIDTH + (uint32_t)x] = color_p->full;
            ++color_p;
        }
    }

    lv_disp_flush_ready(drv);
}

void LVGL_Port_Init(void)
{
    lv_init();

    lv_disp_draw_buf_init(
        &lvgl_disp_buf,
        lvgl_draw_buf,
        NULL,
        LCD_WIDTH * LVGL_DRAW_BUF_LINES);

    lv_disp_drv_init(&lvgl_disp_drv);
    lvgl_disp_drv.hor_res = LCD_WIDTH;
    lvgl_disp_drv.ver_res = LCD_HEIGHT;
    lvgl_disp_drv.flush_cb = LVGL_Flush;
    lvgl_disp_drv.draw_buf = &lvgl_disp_buf;
    lv_disp_drv_register(&lvgl_disp_drv);
}

