static void SD_TryInit(uint32_t now)
{
    if (sd_ready)
    {
        return;
    }

    if ((int32_t)(now - next_retry_ms) < 0)
    {
        return;
    }

    if (SD_Card_Init())
    {
        sd_ready = 1U;
        fail_logged = 0U;
        LOG_Write("SD:INIT_OK\r\n");
    }
    else
    {
        if (!fail_logged)
        {
            LOG_Write("SD:INIT_FAIL\r\n");
            fail_logged = 1U;
        }
        next_retry_ms = now + SD_RETRY_MS;
    }
}

