content.text:
Restore 4-bit SDIO and lower clock. In `sd_card.c`, set `BusWide = SDIO_BUS_WIDE_4B`, `ClockDiv = 8` and call `HAL_SD_ConfigWideBusOperation` after init. Add card info/error logging.

Let's edit `sd_card.c`:
```c
int SD_Card_Init(void) {
  hsd.Instance = SDIO;
  ...
  hsd.Init.BusWide = SDIO_BUS_WIDE_4B;
  hsd.Init.ClockDiv = 8U; // 48/(8+2)=4.8 MHz
  if (HAL_SD_Init(&hsd) != HAL_OK) {
    LOG_Printf("SD:INIT_FAIL err=%lu\r\n", hsd.ErrorCode);
    HAL_SD_DeInit(&hsd);
    return 0;
  }
  if (HAL_SD_ConfigWideBusOperation(&hsd, SDIO_BUS_WIDE_4B) != HAL_OK) {
    LOG_Printf("SD:WIDE_FAIL err=%lu\r\n", hsd.ErrorCode);
    HAL_SD_DeInit(&hsd);
    return 0;
  }
  HAL_SD_CardInfoTypeDef info;
  if (HAL_SD_GetCardInfo(&hsd, &info) == HAL_OK) {
    LOG_Printf("SD:CARD type=%lu blocks=%lu block_size=%lu capacity=%luMB\r\n",
      info.CardType, info.LogBlockNbr, info.LogBlockSize,
      (info.LogBlockNbr / 1024U) * (info.LogBlockSize / 1024U) ...
  }
  return 1;
}
```
Need `log_uart.h` include in `sd_card.c`.
- `HAL_SD_GetCardInfo` signature: `HAL_SD_CardInfoTypeDef *pCardInfo`; fields `CardType`, `CardVersion`, `Class`, `RelCardAdd`, `BlockNbr`, `BlockSize`, `LogBlockNbr`, `LogBlockSize`. We can print `LogBlockNbr`, `LogBlockSize`, and capacity in MB:
  `capacity_MB = (info.LogBlockNbr / 2048) * (info.LogBlockSize / 512)`? Simpler: `uint64_t bytes = (uint64_t)info.LogBlockNbr * info.LogBlockSize; uint32_t mb = bytes / (1024*1024);`
  Use `LOG_Printf` with `%lu` for 32-bit; `unsigned long` on ARM is 32-bit. Cast `(unsigned long)`.
- `hsd.ErrorCode` is a 32-bit field; print it.
- The `HAL_SD_DeInit` after a failed init calls `HAL_SD_MspDeInit` and may deinit PC10; we restored 4-bit, so PC10 is SDIO; no LCD. Fine.
- The `SD_ENABLE_SDIO` flag in `sd_monitor.c` set to 1.
- The MSP SDIO 4-bit configuration restored (PC8-12, PD2), with pull-ups. We need to change the MspInit from 1-bit to 4-bit; and MspDeInit to deinit PC8-12/PD2. This is a reversal of our previous edit. The on-board LCD is not initialized; PC10 is free for SDIO. Good.
- The `.ioc` still has SDIO 4-bit; consistent.
- Lower the clock: `ClockDiv = 8` gives 48/(8+2)=4.8 MHz. If the user wants lower, 16 -> 2.67 MHz. 4.8 MHz is reasonable for 4-bit. We can set 8.

Let's edit `sd_card.c`.

input.content:
#include "sd_card.h"

#include "log_uart.h"
#include "main.h"

extern SD_HandleTypeDef hsd;

int SD_Card_Init(void)
{
    HAL_SD_CardInfoTypeDef card_info;

    hsd.Instance = SDIO;
    hsd.Init.ClockEdge = SDIO_CLOCK_EDGE_RISING;
    hsd.Init.ClockBypass = SDIO_CLOCK_BYPASS_DISABLE;
    hsd.Init.ClockPowerSave = SDIO_CLOCK_POWER_SAVE_DISABLE;
    hsd.Init.BusWide = SDIO_BUS_WIDE_4B;
    hsd.Init.HardwareFlowControl = SDIO_HARDWARE_FLOW_CONTROL_DISABLE;
    /* SDIOCLK is 48 MHz here: 48 / (8 + 2) = 4.8 MHz after initialization. */
    hsd.Init.ClockDiv = 8U;

    if (HAL_SD_Init(&hsd) != HAL_OK)
    {
        LOG_Printf("SD:INIT_FAIL err=%lu\r\n", (unsigned long)hsd.ErrorCode);
        (void)HAL_SD_DeInit(&hsd);
        return 0;
    }

    if (HAL_SD_ConfigWideBusOperation(&hsd, SDIO_BUS_WIDE_4B) != HAL_OK)
    {
        LOG_Printf("SD:WIDE_FAIL err=%lu\r\n", (unsigned long)hsd.ErrorCode);
        (void)HAL_SD_DeInit(&hsd);
        return 0;
    }

    if (HAL_SD_GetCardInfo(&hsd, &card_info) == HAL_OK)
    {
        uint64_t bytes = (uint64_t)card_info.LogBlockNbr * (uint64_t)card_info.LogBlockSize;
        unsigned long capacity_mb = (unsigned long)(bytes / (1024ULL * 1024ULL));

        LOG_Printf(
            "SD:CARD type=%lu blocks=%lu block_size=%lu capacity=%luMB\r\n",
            (unsigned long)card_info.CardType,
            (unsigned long)card_info.LogBlockNbr,
            (unsigned long)card_info.LogBlockSize,
            capacity_mb);
    }

    return 1;
}

void SD_Card_DeInit(void)
{
    (void)HAL_SD_DeInit(&hsd);
}

