#ifndef APP_LOG_UART_H
#define APP_LOG_UART_H

#ifdef __cplusplus
extern "C" {
#endif

#include "main.h"

/** Initialize USART1 TX on PA9 at 115200 8N1. */
void LOG_Init(void);

/** Send a null-terminated string on the log UART. */
void LOG_Write(const char *text);

/** printf-style logging helper (blocking, polled transmit). */
void LOG_Printf(const char *format, ...);

#ifdef __cplusplus
}
#endif

#endif /* APP_LOG_UART_H */

#include "log_uart.h"

#include <stdarg.h>
#include <stdio.h>
#include <string.h>

UART_HandleTypeDef huart1;

void LOG_Init(void)
{
    huart1.Instance = USART1;
    huart1.Init.BaudRate = 115200;
    huart1.Init.WordLength = UART_WORDLENGTH_8B;
    huart1.Init.StopBits = UART_STOPBITS_1;
    huart1.Init.Parity = UART_PARITY_NONE;
    huart1.Init.Mode = UART_MODE_TX;
    huart1.Init.HwFlowCtl = UART_HWCONTROL_NONE;
    huart1.Init.OverSampling = UART_OVERSAMPLING_16;

    if (HAL_UART_Init(&huart1) != HAL_OK)
    {
        Error_Handler();
    }
}

void HAL_UART_MspInit(UART_HandleTypeDef *huart)
{
    GPIO_InitTypeDef GPIO_InitStruct = {0};

    if (huart->Instance == USART1)
    {
        __HAL_RCC_USART1_CLK_ENABLE();
        __HAL_RCC_GPIOA_CLK_ENABLE();

        GPIO_InitStruct.Pin = GPIO_PIN_9;
        GPIO_InitStruct.Mode = GPIO_MODE_AF_PP;
        GPIO_InitStruct.Pull = GPIO_NOPULL;
        GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_VERY_HIGH;
        GPIO_InitStruct.Alternate = GPIO_AF7_USART1;
        HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);
    }
}

void HAL_UART_MspDeInit(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1)
    {
        __HAL_RCC_USART1_CLK_DISABLE();
        HAL_GPIO_DeInit(GPIOA, GPIO_PIN_9);
    }
}

void LOG_Write(const char *text)
{
    if (text == NULL)
    {
        return;
    }

    size_t length = strlen(text);
    if (length == 0U)
    {
        return;
    }

    if (length > 0xFFFFU)
    {
        length = 0xFFFFU;
    }

    (void)HAL_UART_Transmit(&huart1, (uint8_t *)text, (uint16_t)length, 1000U);
}

void LOG_Printf(const char *format, ...)
{
    char buffer[160];
    va_list args;

    if (format == NULL)
    {
        return;
    }

    va_start(args, format);
    (void)vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    buffer[sizeof(buffer) - 1U] = '\0';
    LOG_Write(buffer);
}

