Implementation:
```
#define SD_RESERVED_MB 1U
#define SD_MIN_PART2_MB 64U
int SD_PartitionPlan_Compute(...) {
  if (!plan || total_mb == 0) return 0;
  plan->total_mb = total_mb;
  plan->part1_mb = 0; plan->part2_mb = 0; plan->valid = 0;
  if (total_mb <= SD_RESERVED_MB + SD_MIN_PART2_MB) return 0;
  uint32_t usable = total_mb - SD_RESERVED_MB;
  if (usable > first_partition_mb + SD_MIN_PART2_MB) {
    plan->part1_mb = first_partition_mb;
    plan->part2_mb = usable - first_partition_mb;
    plan->valid = 1;
  } else {
    plan->part1_mb = usable - SD_MIN_PART2_MB;
    plan->part2_mb = SD_MIN_PART2_MB;
    plan->valid = 1; // or 0 if card too small
  }
  return plan->valid;
}
