#ifndef APP_SD_PARTITION_H
#define APP_SD_PARTITION_H

#ifdef __cplusplus
extern "C" {
#endif

#include <stdint.h>

typedef struct
{
    uint32_t total_mb;
    uint32_t part1_mb;
    uint32_t part2_mb;
    uint8_t valid;
} SD_PartitionPlan;

/**
 * @brief Compute a two-partition plan from the card's real capacity.
 *
 * Partition 1 is 4096 MB when the card is large enough. Partition 2 gets the
 * remaining space minus 1 MB reserved for the MBR/alignment. If the card is
 * too small for 4 GB + a 64 MB second partition, the first partition is
 * reduced to 75% of the usable space.
 *
 * @return 1 when a plan is produced, 0 when the card is too small.
 */
int SD_PartitionPlan_Compute(uint32_t total_mb, SD_PartitionPlan *plan);

#ifdef __cplusplus
}
#endif

#endif /* APP_SD_PARTITION_H */

#include "sd_partition.h"

#define SD_FIRST_PARTITION_MB 4096U
#define SD_RESERVED_MB        1U
#define SD_MIN_SECOND_MB      64U

int SD_PartitionPlan_Compute(uint32_t total_mb, SD_PartitionPlan *plan)
{
    uint32_t usable_mb;

    if (plan == NULL || total_mb <= SD_RESERVED_MB)
    {
        return 0;
    }

    plan->total_mb = total_mb;
    plan->part1_mb = 0U;
    plan->part2_mb = 0U;
    plan->valid = 0U;

    usable_mb = total_mb - SD_RESERVED_MB;

    if (usable_mb >= (SD_FIRST_PARTITION_MB + SD_MIN_SECOND_MB))
    {
        plan->part1_mb = SD_FIRST_PARTITION_MB;
        plan->part2_mb = usable_mb - SD_FIRST_PARTITION_MB;
    }
    else
    {
        if (usable_mb <= SD_MIN_SECOND_MB)
        {
            return 0;
        }

        /* Card smaller than 4 GB + 64 MB: reduce partition 1 and keep a
         * minimum second partition. */
        plan->part1_mb = (usable_mb * 3U) / 4U;
        plan->part2_mb = usable_mb - plan->part1_mb;
    }

    plan->valid = 1U;
    return 1;
}

