/**
 * @brief Write, then read back and verify block_count blocks.
 *
 * Reports both write and read throughput and counts verification errors.
 */
int SD_TestReadWrite(
    uint32_t start_lba,
    uint32_t block_count,
    SD_SpeedTestResult *result);

