  if (HAL_SD_ReadBlocks(...) != HAL_OK) { LOG_Printf("SD:TEST_READ_FAIL err=%lu\r\n", ...); return 0; }
  uint32_t pattern = 0x5AA5AA55U ^ offset;
  for (i=0;i<1024;i++) if (sd_test_buffer[i]!=pattern) errors++;
}
result->read_ms=...
result->read_kbs=...
result->verify_errors=errors;
result->success = errors==0;
LOG_Printf("SD:TEST_READ blocks=%lu bytes=%lu time=%lu ms speed=%lu KB/s verify=%s\r\n", ...);
LOG_Printf("SD:TEST_RESULT write=%lu KB/s read=%lu KB/s verify_errors=%lu\r\n", ...);
return result->success;
```
- The read buffer size is 4KB = 8 blocks; the read function reads `chunk` blocks into the4KB buffer; fine.
- The `SD_TestWriteSpeed` fills the buffer with pattern per chunk; the read/verify expects the same pattern per chunk. Good.
- The `SD_TestReadSpeed` standalone reads and discards.
- `memset` result to0; include `<string.h>`.
- Use `unsigned long` casts for `%lu`.
- The `SD_TestReadWrite` reports write speed via `SD_TestWriteSpeed`, then read/verify. The result struct has both.
- The test is destructive; we can log a warning before writing: `LOG_Write("SD:TEST_WRITE 1MB destructive\r\n")`. But maybe just proceed. The user wants tests. We can add a log.

Let's write.

input.content:
#include "sd_test.h"

#include <string.h>

#include "log_uart.h"
#include "sd_card.h"

#define SD_TEST_CHUNK_BLOCKS 8U
#define SD_TEST_BUFFER_WORDS 1024U

static uint32_t sd_test_buffer[SD_TEST_BUFFER_WORDS] __attribute__((aligned(4)));

static void SD_Test_FillBuffer(uint32_t pattern)
{
    uint32_t index;

    for (index = 0U; index < SD_TEST_BUFFER_WORDS; ++index)
    {
        sd_test_buffer[index] = pattern;
    }
}

static uint32_t SD_Test_Kbps(uint32_t blocks, uint32_t elapsed_ms)
{
    if (elapsed_ms == 0U)
    {
        elapsed_ms = 1U;
    }

    return (blocks * 512U * 1000U) / (elapsed_ms * 1024U);
}

int SD_TestWriteSpeed(
    uint32_t start_lba,
    uint32_t block_count,
    SD_SpeedTestResult *result)
{
    uint32_t offset;
    uint32_t chunk;
    uint32_t pattern;
    uint32_t start_tick;
    uint32_t elapsed;

    if (result == NULL || block_count == 0U)
    {
        return 0;
    }

    (void)memset(result, 0, sizeof(*result));
    result->start_lba = start_lba;
    result->block_count = block_count;

    LOG_Write("SD:TEST_WRITE_START (destructive)\r\n");

    start_tick = HAL_GetTick();

    for (offset = 0U; offset < block_count; offset += chunk)
    {
        chunk = block_count - offset;
        if (chunk > SD_TEST_CHUNK_BLOCKS)
        {
            chunk = SD_TEST_CHUNK_BLOCKS;
        }

        pattern = 0x5AA5AA55U ^ offset;
        SD_Test_FillBuffer(pattern);

        if (HAL_SD_WriteBlocks(&hsd, sd_test_buffer, start_lba + offset, chunk, 5000U) != HAL_OK)
        {
            LOG_Printf("SD:TEST_WRITE_FAIL err=%lu\r\n", (unsigned long)hsd.ErrorCode);
            return 0;
        }
    }

    elapsed = HAL_GetTick() - start_tick;
    if (elapsed == 0U)
    {
        elapsed = 1U;
    }

    result->write_ms = elapsed;
    result->write_kbs = SD_Test_Kbps(block_count, elapsed);
    result->success = 1;

    LOG_Printf(
        "SD:TEST_WRITE blocks=%lu bytes=%lu time=%lu ms speed=%lu KB/s\r\n",
        (unsigned long)block_count,
        (unsigned long)(block_count * 512U),
        (unsigned long)elapsed,
        (unsigned long)result->write_kbs);

    return 1;
}

int SD_TestReadSpeed(
    uint32_t start_lba,
    uint32_t block_count,
    SD_SpeedTestResult *result)
{
    uint32_t offset;
    uint32_t chunk;
    uint32_t start_tick;
    uint32_t elapsed;

    if (result == NULL || block_count == 0U)
    {
        return 0;
    }

    LOG_Write("SD:TEST_READ_START\r\n");

    start_tick = HAL_GetTick();

    for (offset = 0U; offset < block_count; offset += chunk)
    {
        chunk = block_count - offset;
        if (chunk > SD_TEST_CHUNK_BLOCKS)
        {
            chunk = SD_TEST_CHUNK_BLOCKS;
        }

        if (HAL_SD_ReadBlocks(&hsd, sd_test_buffer, start_lba + offset, chunk, 5000U) != HAL_OK)
        {
            LOG_Printf("SD:TEST_READ_FAIL err=%lu\r\n", (unsigned long)hsd.ErrorCode);
            return 0;
        }
    }

    elapsed = HAL_GetTick() - start_tick;
    if (elapsed == 0U)
    {
        elapsed = 1U;
    }

    result->read_ms = elapsed;
    result->read_kbs = SD_Test_Kbps(block_count, elapsed);

    LOG_Printf(
        "SD:TEST_READ blocks=%lu bytes=%lu time=%lu ms speed=%lu KB/s\r\n",
        (unsigned long)block_count,
        (unsigned long)(block_count * 512U),
        (unsigned long)elapsed,
        (unsigned long)result->read_kbs);

    return 1;
}

int SD_TestReadWrite(
    uint32_t start_lba,
    uint32_t block_count,
    SD_SpeedTestResult *result)
{
    uint32_t offset;
    uint32_t chunk;
    uint32_t pattern;
    uint32_t start_tick;
    uint32_t elapsed;
    uint32_t errors = 0U;
    uint32_t index;

    if (result == NULL || block_count == 0U)
    {
        return 0;
    }

    if (!SD_TestWriteSpeed(start_lba, block_count, result))
    {
        return 0;
    }

    LOG_Write("SD:TEST_VERIFY_START\r\n");

    start_tick = HAL_GetTick();

    for (offset = 0U; offset < block_count; offset += chunk)
    {
        chunk = block_count - offset;
        if (chunk > SD_TEST_CHUNK_BLOCKS)
        {
            chunk = SD_TEST_CHUNK_BLOCKS;
        }

        if (HAL_SD_ReadBlocks(&hsd, sd_test_buffer, start_lba + offset, chunk, 5000U) != HAL_OK)
        {
            LOG_Printf("SD:TEST_READ_FAIL err=%lu\r\n", (unsigned long)hsd.ErrorCode);
            return 0;
        }

        pattern = 0x5AA5AA55U ^ offset;
        for (index = 0U; index < SD_TEST_BUFFER_WORDS; ++index)
        {
            if (sd_test_buffer[index] != pattern)
            {
                ++errors;
            }
        }
    }

    elapsed = HAL_GetTick() - start_tick;
    if (elapsed == 0U)
    {
        elapsed = 1U;
    }

    result->read_ms = elapsed;
    result->read_kbs = SD_Test_Kbps(block_count, elapsed);
    result->verify_errors = errors;
    result->success = (errors == 0U) ? 1 : 0;

    LOG_Printf(
        "SD:TEST_READ blocks=%lu bytes=%lu time=%lu ms speed=%lu KB/s verify_errors=%lu\r\n",
        (unsigned long)block_count,
        (unsigned long)(block_count * 512U),
        (unsigned long)elapsed,
        (unsigned long)result->read_kbs,
        (unsigned long)errors);

    LOG_Printf(
        "SD:TEST_RESULT write=%lu KB/s read=%lu KB/s verify=%s\r\n",
        (unsigned long)result->write_kbs,
        (unsigned long)result->read_kbs,
        (result->success ? "OK" : "FAIL"));

    return result->success;
}

