Conditional test in `sd_monitor.c`. Current block:
```
#if SD_CREATE_PARTITIONS_ON_INIT
        LOG_Write("SD:PARTITIONS_CREATE requested\r\n");
        (void)SD_CreatePartitions(4096U);
#endif

#if SD_RUN_SPEED_TEST_ON_INIT
        {
            ...
        }
#endif
```
Change to:
```
#if SD_CREATE_PARTITIONS_ON_INIT
        LOG_Write("SD:PARTITIONS_CREATE requested\r\n");
        if (!SD_CreatePartitions(4096U)) {
            LOG_Write("SD:TEST_SKIPPED (partitions failed)\r\n");
        } else {
            LOG_Write("SD:PARTITIONS_OK\r\n");
#if SD_RUN_SPEED_TEST_ON_INIT
            { run test }
#endif
        }
#else
#if SD_RUN_SPEED_TEST_ON_INIT
        { run test }
#endif
#endif
```
This avoids duplicate code; we can define a macro/function for the test. Simpler: use a `uint8_t can_test = 1;`:
```
#if SD_CREATE_PARTITIONS_ON_INIT
  LOG...
  if (!SD_CreatePartitions(...)) { can_test =0; LOG_Write("SD:TEST_SKIPPED..."); }
  else { LOG_Write("SD:PARTITIONS_OK"); }
#endif
#if SD_RUN_SPEED_TEST_ON_INIT
  if (can_test) { ... }
#endif
```
