#ifndef APP_SD_DISKIO_H
#define APP_SD_DISKIO_H

#include "ff_gen_drv.h"

#ifdef __cplusplus
extern "C" {
#endif

/** FatFs driver entry, bound to the data partition (partition 2). */
extern Diskio_drvTypeDef SD_Driver;

/** Start LBA and size (in 512-byte sectors) of the FatFs partition. */
int SD_Diskio_PartitionInfo(uint32_t *base_lba, uint32_t *sectors);

#ifdef __cplusplus
}
#endif

#endif /* APP_SD_DISKIO_H */

#include "sd_diskio.h"

#include <string.h>

#include "sd_card.h"

#define SD_SECTOR_SIZE        512U
#define SD_TRANSFER_TIMEOUT   5000U

/* Partition entry type values that can hold a FAT/exFAT filesystem. */
static int SD_Diskio_IsFatType(uint8_t type)
{
    switch (type)
    {
        case 0x01U: /* FAT12 */
        case 0x04U: /* FAT16 < 32 MB */
        case 0x06U: /* FAT16 */
        case 0x0BU: /* FAT32 CHS */
        case 0x0CU: /* FAT32 LBA */
        case 0x07U: /* exFAT / NTFS */
        case 0x0EU: /* FAT16 LBA */
            return 1;
        default:
            return 0;
    }
}

static uint32_t SD_Diskio_ReadU32(const uint8_t *buffer)
{
    return (uint32_t)buffer[0]
         | ((uint32_t)buffer[1] << 8U)
         | ((uint32_t)buffer[2] << 16U)
         | ((uint32_t)buffer[3] << 24U);
}

/* Bounce buffer for transfers whose caller buffer is not word aligned. */
static uint8_t sd_disk_bounce[SD_SECTOR_SIZE] __attribute__((aligned(32)));
static uint8_t sd_disk_mbr[SD_SECTOR_SIZE] __attribute__((aligned(32)));

static DSTATUS sd_disk_status = STA_NOINIT;
static uint32_t sd_disk_base_lba;
static uint32_t sd_disk_sectors;

static int SD_Diskio_RawRead(uint32_t lba, uint8_t *dst, uint32_t blocks)
{
    if (HAL_SD_ReadBlocks_DMA(&hsd, dst, lba, blocks) != HAL_OK)
    {
        return 0;
    }

    return SD_WaitTransfer(SD_TRANSFER_TIMEOUT);
}

static int SD_Diskio_RawWrite(uint32_t lba, const uint8_t *src, uint32_t blocks)
{
    if (HAL_SD_WriteBlocks_DMA(&hsd, (uint8_t *)src, lba, blocks) != HAL_OK)
    {
        return 0;
    }

    return SD_WaitTransfer(SD_TRANSFER_TIMEOUT);
}

/**
 * Read the MBR and locate the FAT partition that FatFs should expose.
 * Partition 1 is the internal raw area (non-FAT type) and is deliberately
 * skipped: only the user-visible data partition is mounted.
 */
static int SD_Diskio_FindPartition(void)
{
    uint32_t index;

    for (index = 0U; index < 4U; ++index)
    {
        const uint8_t *entry = &sd_disk_mbr[446U + (index * 16U)];
        uint8_t type = entry[4U];

        if (!SD_Diskio_IsFatType(type))
        {
            continue;
        }

        sd_disk_base_lba = SD_Diskio_ReadU32(&entry[8U]);
        sd_disk_sectors = SD_Diskio_ReadU32(&entry[12U]);

        if (sd_disk_base_lba != 0U && sd_disk_sectors != 0U)
        {
            return 1;
        }
    }

    return 0;
}

static DSTATUS SD_Diskio_Init(BYTE lun)
{
    (void)lun;

    sd_disk_status = STA_NOINIT;
    sd_disk_base_lba = 0U;
    sd_disk_sectors = 0U;

    if (!SD_Diskio_RawRead(0U, sd_disk_mbr, 1U))
    {
        return sd_disk_status;
    }

    if (sd_disk_mbr[510U] != 0x55U || sd_disk_mbr[511U] != 0xAAU)
    {
        return sd_disk_status;
    }

    if (!SD_Diskio_FindPartition())
    {
        return sd_disk_status;
    }

    sd_disk_status = 0U;
    return sd_disk_status;
}

static DSTATUS SD_Diskio_Status(BYTE lun)
{
    (void)lun;
    return sd_disk_status;
}

static DRESULT SD_Diskio_Read(BYTE lun, BYTE *buff, DWORD sector, UINT count)
{
    (void)lun;

    if ((sd_disk_status & STA_NOINIT) != 0U)
    {
        return RES_NOTRDY;
    }

    if (buff == NULL || count == 0U)
    {
        return RES_PARERR;
    }

    /* Out-of-partition access is a caller bug: never touch another area. */
    if ((sector + count) > sd_disk_sectors)
    {
        return RES_PARERR;
    }

    if (((uint32_t)buff & 3U) == 0U)
    {
        return SD_Diskio_RawRead(sd_disk_base_lba + sector, buff, count) ? RES_OK : RES_ERROR;
    }

    {
        UINT index;

        for (index = 0U; index < count; ++index)
        {
            if (!SD_Diskio_RawRead(sd_disk_base_lba + sector + index, sd_disk_bounce, 1U))
            {
                return RES_ERROR;
            }
            memcpy(&buff[index * SD_SECTOR_SIZE], sd_disk_bounce, SD_SECTOR_SIZE);
        }
    }

    return RES_OK;
}

static DRESULT SD_Diskio_Write(BYTE lun, const BYTE *buff, DWORD sector, UINT count)
{
    (void)lun;

    if ((sd_disk_status & STA_NOINIT) != 0U)
    {
        return RES_NOTRDY;
    }

    if (buff == NULL || count == 0U)
    {
        return RES_PARERR;
    }

    if ((sector + count) > sd_disk_sectors)
    {
        return RES_PARERR;
    }

    if (((uint32_t)buff & 3U) == 0U)
    {
        return SD_Diskio_RawWrite(sd_disk_base_lba + sector, buff, count) ? RES_OK : RES_ERROR;
    }

    {
        UINT index;

        for (index = 0U; index < count; ++index)
        {
            memcpy(sd_disk_bounce, &buff[index * SD_SECTOR_SIZE], SD_SECTOR_SIZE);
            if (!SD_Diskio_RawWrite(sd_disk_base_lba + sector + index, sd_disk_bounce, 1U))
            {
                return RES_ERROR;
            }
        }
    }

    return RES_OK;
}

static DRESULT SD_Diskio_Ioctl(BYTE lun, BYTE cmd, void *buff)
{
    (void)lun;

    if ((sd_disk_status & STA_NOINIT) != 0U)
    {
        return RES_NOTRDY;
    }

    switch (cmd)
    {
        case CTRL_SYNC:
            return SD_WaitReady(SD_TRANSFER_TIMEOUT) ? RES_OK : RES_ERROR;

        case GET_SECTOR_COUNT:
            *(DWORD *)buff = sd_disk_sectors;
            return RES_OK;

        case GET_SECTOR_SIZE:
            *(WORD *)buff = SD_SECTOR_SIZE;
            return RES_OK;

        case GET_BLOCK_SIZE:
            *(DWORD *)buff = 1U;
            return RES_OK;

        default:
            return RES_PARERR;
    }
}

Diskio_drvTypeDef SD_Driver =
{
    SD_Diskio_Init,
    SD_Diskio_Status,
    SD_Diskio_Read,
    SD_Diskio_Write,
    SD_Diskio_Ioctl,
};

int SD_Diskio_PartitionInfo(uint32_t *base_lba, uint32_t *sectors)
{
    if ((sd_disk_status & STA_NOINIT) != 0U)
    {
        return 0;
    }

    if (base_lba != NULL)
    {
        *base_lba = sd_disk_base_lba;
    }

    if (sectors != NULL)
    {
        *sectors = sd_disk_sectors;
    }

    return 1;
}

#ifndef APP_SD_FS_H
#define APP_SD_FS_H

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/**
 * @brief Mount the user data partition (partition 2) as FatFs drive "0:".
 *
 * Partition 1 is the internal raw area used by the looper; it is not exposed
 * to FatFs and stays invisible on a PC.
 *
 * @param format_if_missing 1 to create a FAT32 volume when no filesystem is
 *                          found. This erases partition 2.
 * @return 1 on success, 0 on failure.
 */
int SD_FS_Mount(int format_if_missing);

/** Unmount the drive and release the FatFs link. */
void SD_FS_Unmount(void);

/** FatFs path of the mounted volume ("0:"), or NULL when not mounted. */
const char *SD_FS_Path(void);

/** 1 when the volume is mounted. */
int SD_FS_IsMounted(void);

/** Log free/total space of the mounted volume. */
void SD_FS_LogUsage(void);

/** Log the root directory entries (debug helper). */
void SD_FS_LogRoot(void);

#ifdef __cplusplus
}
#endif

#endif /* APP_SD_FS_H */

#include "sd_fs.h"

#include <string.h>

#include "ff.h"
#include "ff_gen_drv.h"
#include "log_uart.h"
#include "sd_diskio.h"

#define SD_FS_WORK_SIZE 4096U

static FATFS sd_fatfs;
static char sd_fs_path[4];
static int sd_fs_linked;
static int sd_fs_mounted;

/* f_mkfs() work area: must be at least one sector, 4 KB is comfortable. */
static uint8_t sd_fs_work[SD_FS_WORK_SIZE] __attribute__((aligned(32)));

int SD_FS_Mount(int format_if_missing)
{
    FRESULT result;
    uint32_t base_lba = 0U;
    uint32_t sectors = 0U;

    if (sd_fs_mounted)
    {
        return 1;
    }

    if (!sd_fs_linked)
    {
        if (FATFS_LinkDriver(&SD_Driver, sd_fs_path) != 0)
        {
            LOG_Write("SD:FS_LINK_FAIL\r\n");
            return 0;
        }
        sd_fs_linked = 1;
    }

    result = f_mount(&sd_fatfs, sd_fs_path, 1);

    if (result == FR_NO_FILESYSTEM && format_if_missing)
    {
        LOG_Write("SD:FS_FORMAT_START (erases partition 2)\r\n");

        result = f_mkfs(sd_fs_path, FM_FAT32, 0U, sd_fs_work, sizeof(sd_fs_work));
        if (result != FR_OK)
        {
            LOG_Printf("SD:FS_FORMAT_FAIL res=%u\r\n", (unsigned)result);
            (void)f_mount(NULL, sd_fs_path, 0);
            return 0;
        }

        LOG_Write("SD:FS_FORMAT_OK\r\n");

        /* f_mkfs() leaves the volume unmounted: mount the fresh filesystem. */
        result = f_mount(&sd_fatfs, sd_fs_path, 1);
    }

    if (result != FR_OK)
    {
        LOG_Printf("SD:FS_MOUNT_FAIL res=%u\r\n", (unsigned)result);
        (void)f_mount(NULL, sd_fs_path, 0);
        FATFS_UnLinkDriver(sd_fs_path);
        sd_fs_linked = 0;
        return 0;
    }

    sd_fs_mounted = 1;

    if (SD_Diskio_PartitionInfo(&base_lba, &sectors))
    {
        LOG_Printf(
            "SD:FS_MOUNT_OK drive=%s lba=%lu sectors=%lu\r\n",
            sd_fs_path,
            (unsigned long)base_lba,
            (unsigned long)sectors);
    }
    else
    {
        LOG_Printf("SD:FS_MOUNT_OK drive=%s\r\n", sd_fs_path);
    }

    SD_FS_LogUsage();
    return 1;
}

void SD_FS_Unmount(void)
{
    if (!sd_fs_mounted)
    {
        return;
    }

    (void)f_mount(NULL, sd_fs_path, 0);
    FATFS_UnLinkDriver(sd_fs_path);
    sd_fs_linked = 0;
    sd_fs_mounted = 0;
}

const char *SD_FS_Path(void)
{
    return sd_fs_mounted ? sd_fs_path : NULL;
}

int SD_FS_IsMounted(void)
{
    return sd_fs_mounted;
}

void SD_FS_LogUsage(void)
{
    FATFS *fs = NULL;
    DWORD free_clusters = 0U;
    FRESULT result;
    uint64_t total_bytes;
    uint64_t free_bytes;
    uint32_t cluster_bytes;

    if (!sd_fs_mounted)
    {
        return;
    }

    result = f_getfree(sd_fs_path, &free_clusters, &fs);
    if (result != FR_OK || fs == NULL)
    {
        LOG_Printf("SD:FS_USAGE_FAIL res=%u\r\n", (unsigned)result);
        return;
    }

    cluster_bytes = (uint32_t)fs->csize * 512U;
    total_bytes = (uint64_t)(fs->n_fatent - 2U) * cluster_bytes;
    free_bytes = (uint64_t)free_clusters * cluster_bytes;

    LOG_Printf(
        "SD:FS_USAGE total=%luMB free=%luMB cluster=%luB\r\n",
        (unsigned long)(total_bytes / (1024ULL * 1024ULL)),
        (unsigned long)(free_bytes / (1024ULL * 1024ULL)),
        (unsigned long)cluster_bytes);
}

void SD_FS_LogRoot(void)
{
    DIR dir;
    FILINFO info;
    FRESULT result;
    uint32_t count = 0U;

    if (!sd_fs_mounted)
    {
        return;
    }

    result = f_opendir(&dir, sd_fs_path);
    if (result != FR_OK)
    {
        LOG_Printf("SD:FS_OPENDIR_FAIL res=%u\r\n", (unsigned)result);
        return;
    }

    for (;;)
    {
        result = f_readdir(&dir, &info);
        if (result != FR_OK || info.fname[0] == '\0')
        {
            break;
        }

        LOG_Printf(
            "SD:FS_ENTRY name=%s size=%lu attr=0x%02X\r\n",
            info.fname,
            (unsigned long)info.fsize,
            (unsigned)info.fattrib);

        if (++count >= 32U)
        {
            break;
        }
    }

    (void)f_closedir(&dir);
    LOG_Printf("SD:FS_ROOT entries=%lu\r\n", (unsigned long)count);
}

